use crate::api_description::ExtensionMode;
use crate::{
    ApiEndpointBodyContentType, Extractor, ExtractorMetadata, HttpError,
    RequestContext, ServerContext,
};
use async_trait::async_trait;
use http::header;
use http::Response;
use http::StatusCode;
use hyper::upgrade::OnUpgrade;
